package kr.remerge.stylehub.domain.product.repository;

import jakarta.persistence.EntityManager;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
@RequiredArgsConstructor
public class ProductSearchRepository {
    private final EntityManager em;

    public List<Product> searchByName(String keyword, String sort) {
        String sql = "select * from products where name like '%" + keyword + "%' order by " + sort;
        return em.createNativeQuery(sql, Product.class).getResultList();
    }
}

package kr.remerge.stylehub.domain.product.service;

import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.ArrayList;
import java.util.List;

@Service
@RequiredArgsConstructor
public class ProductSearchService {
    private final ProductSearchRepository searchRepository;
    private final ProductOptionRepository optionRepository;

    // GET /api/products/search?keyword=...&sort=...
    @Transactional(readOnly = true)
    public List<ProductSearchResponse> search(String keyword, String sort) {
        List<Product> products = searchRepository.searchByName(keyword, sort);
        List<ProductSearchResponse> out = new ArrayList<>();
        for (Product p : products) {
            List<ProductOption> options = optionRepository.findByProductId(p.getId());
            out.add(ProductSearchResponse.of(p, options));
        }
        return out;
    }
}
